    for (int len = 2; len <= m; len += 2) {
        for (int i = 1; i + len - 1 <= m; i++) {
            int j = i + len - 1;
            // Try pairing a[i] with a[k+1], after removing i+1..k
            for (int k = i; k <= j; k += 2) {
                // k = i: pair i with i+1 directly
                int mid = k; // a[i] pairs with a[k+1], need dp[i+1][k] true (empty if k=i)
                int left_ok = (k == i) ? 1 : dp[i+1][k];
                if (left_ok && abs(a[i] - a[k+1]) <= 1) {
                    int right_ok = (k+2 > j) ? 1 : dp[k+2][j];
