static int abs_int(int x) { return x < 0 ? -x : x; }

int main(void) {
    int n;
    while (scanf("%d", &n) == 1 && n) {
        int *w = (int *)malloc(sizeof(int) * n);
        for (int i = 0; i < n; i++) scanf("%d", &w[i]);

        /* dp[l][r] = maximum removable blocks in interval [l, r] */
        int **dp = (int **)malloc(sizeof(int *) * n);
        for (int i = 0; i < n; i++) {
            dp[i] = (int *)calloc(n, sizeof(int));
        }

        for (int len = 2; len <= n; len++) {
            for (int l = 0; l + len - 1 < n; l++) {
                int r = l + len - 1;

                /* Case 1: remove whole interval if possible */
                if (abs_int(w[l] - w[r]) <= 1) {
                    if (len == 2) {
                        dp[l][r] = 2;
                    } else if (dp[l + 1][r - 1] == len - 2) {
                        dp[l][r] = len;
                    }
                }

                /* Case 2: split interval */
                for (int k = l; k < r; k++) {
                    int cand = dp[l][k] + dp[k + 1][r];
                    if (cand > dp[l][r]) dp[l][r] = cand;
                }
            }
        }

        printf("%d\n", dp[0][n - 1]);

        for (int i = 0; i < n; i++) free(dp[i]);
        free(dp);
        free(w);
    }
    return 0;
}

