    cin.tie(nullptr);

    int n;
    cin >> n;
    vector<int> w(n);
    for (int i = 0; i < n; i++) cin >> w[i];

    vector<vector<int>> dp(n, vector<int>(n, 0));

    for (int len = 1; len <= n; len++) {
        for (int l = 0; l + len - 1 < n; l++) {
            int r = l + len - 1;
            if (len == 1) {
                dp[l][r] = 0;
            } else if (len == 2) {
                if (abs(w[l] - w[r]) <= 1) dp[l][r] = 2;
                else dp[l][r] = 0;
            } else {
                // try removing l and r together if inside can be fully removed
                if (abs(w[l] - w[r]) <= 1 && dp[l+1][r-1] == len - 2) {
                    dp[l][r] = len;
                }
                // try splitting
                for (int k = l; k < r; k++) {
                    dp[l][r] = max(dp[l][r], dp[l][k] + dp[k+1][r]);
                }
            }
        }
    }

    cout << dp[0][n-1] << "\n";
