int main() {
    int n;
    cin >> n;
    vector<int> w(n+1);
    for (int i = 1; i <= n; i++) cin >> w[i];

    // dp[i][j] = can we remove all blocks from i to j?
    vector<vector<bool>> dp(n+2, vector<bool>(n+2, false));

    // length 2
    for (int i = 1; i+1 <= n; i++) {
        if (abs(w[i] - w[i+1]) <= 1) dp[i][i+1] = true;
    }

    // longer even lengths
    for (int len = 4; len <= n; len += 2) {
        for (int i = 1; i+len-1 <= n; i++) {
            int j = i+len-1;
            // option 1: pair i and j, remove middle
            if (dp[i+1][j-1] && abs(w[i]-w[j]) <= 1) {
                dp[i][j] = true;
                continue;
            }
            // option 2: split
            for (int k = i+1; k < j; k += 2) {
                if (dp[i][k] && dp[k+1][j]) {
                    dp[i][j] = true;
                    break;
                }
            }
        }
    }

    // f[i] = max blocks removable from first i blocks
    vector<int> f(n+1, 0);
    for (int i = 1; i <= n; i++) {
        f[i] = f[i-1]; // don't remove block i
        for (int j = 1; j <= i; j++) {
            if ((i-j+1) % 2 == 0 && dp[j][i]) {
                f[i] = max(f[i], f[j-1] + (i-j+1));
            }
        }
    }

    cout << f[n] << endl;
    return 0;
}

