        for (int len = 2; len <= n; ++len) {
            for (int l = 0; l + len <= n; ++l) {
                int r = l + len;

                // If inside can be fully removed and ends differ by at most 1,
                // then the whole interval can be removed.
                if (abs(w[l] - w[r - 1]) <= 1) {
                    if (len == 2 || dp[l + 1][r - 1] == len - 2) {
                        dp[l][r] = len;
                    }
                }

                // Split into two parts
                for (int m = l + 1; m < r; ++m) {
                    dp[l][r] = max(dp[l][r], dp[l][m] + dp[m][r]);
                }
            }
        }

        cout << dp[0][n] << '\n';
    }

    return 0;
