        // blocks 2..n are removable
        boolean[][] dp = new boolean[n + 2][n + 2];

        // Fill for lengths 2, 4, 6, ...
        for (int len = 2; len <= n; len += 2) {
            for (int i = 2; i + len - 1 <= n; i++) {
                int j = i + len - 1;
                // Option 1: i and j are removed as a pair, with i+1..j-1 removed first
                if (len == 2) {
                    dp[i][j] = Math.abs(w[i] - w[j]) <= 1;
                } else {
                    if (dp[i + 1][j - 1] && Math.abs(w[i] - w[j]) <= 1) {
                        dp[i][j] = true;
                    }
                }
                // Option 2: split
                if (!dp[i][j]) {
                    for (int k = i + 1; k < j; k += 2) {
                        if (dp[i][k] && dp[k + 1][j]) {
                            dp[i][j] = true;
                            break;
                        }
                    }
                }
            }
        }

        // maxRemove[i] = max blocks removable from i..n
        int[] maxRemove = new int[n + 2];
        for (int i = n; i >= 2; i--) {
            maxRemove[i] = maxRemove[i + 1]; // skip block i
            for (int j = i + 1; j <= n; j += 2) {
                if (dp[i][j]) {
                    maxRemove[i] = Math.max(maxRemove[i], (j - i + 1) + maxRemove[j + 1]);
                }
            }
        }

        System.out.println(maxRemove[2]);
    }
}

