public class Main {
    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        StringBuilder out = new StringBuilder();

        while (true) {
            int n;
            try {
                n = fs.nextInt();
            } catch (Exception e) {
                break;
            }
            if (n == 0) break;

            int[] w = new int[n];
            for (int i = 0; i < n; i++) w[i] = fs.nextInt();

            // dp[l][r] = maximum removable blocks in interval [l, r]
            int[][] dp = new int[n][n];

            // full[l][r] = whether whole interval [l, r] can be removed
            boolean[][] full = new boolean[n][n];

            for (int len = 2; len <= n; len++) {
                for (int l = 0; l + len - 1 < n; l++) {
                    int r = l + len - 1;

                    // Check if whole interval can be removed
                    if (Math.abs(w[l] - w[r]) <= 1) {
                        if (len == 2) {
                            full[l][r] = true;
                        } else if (full[l + 1][r - 1]) {
                            full[l][r] = true;
                        }
                    }

                    if (full[l][r]) {
                        dp[l][r] = len;
                    }

                    // Split interval
                    for (int k = l; k < r; k++) {
                        dp[l][r] = Math.max(dp[l][r], dp[l][k] + dp[k + 1][r]);
                    }
                }
            }

            out.append(n == 0 ? 0 : dp[0][n - 1]).append('\n');
        }

        System.out.print(out.toString());
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
                if (c == -1) throw new EOFException();
            } while (c <= ' ');

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }
}

