from functools import lru_cache

def solve():
    input_data = sys.stdin.read().split()
    idx = 0
    n = int(input_data[idx]); idx += 1
    a = []
    for i in range(n):
        a.append(int(input_data[idx])); idx += 1

    # blocks to potentially remove: a[0..n-2], a[n-1] is Dharma (top, stays)
    blocks = a[:n-1]
    m = len(blocks)

    # can[i][j] = can we remove all blocks from i to j (0-indexed, inclusive, j-i+1 even)
    can = [[False]*m for _ in range(m)]

    for length in range(2, m+1, 2):
        for i in range(m - length + 1):
            j = i + length - 1
            # Case 1: remove i and j last, after removing i+1..j-1
            if length == 2:
                can[i][j] = abs(blocks[i] - blocks[j]) <= 1
            else:
                if can[i+1][j-1] and abs(blocks[i] - blocks[j]) <= 1:
                    can[i][j] = True
                # Case 2: split
                if not can[i][j]:
                    for k in range(i+1, j, 2):
                        if can[i][k] and can[k+1][j]:
                            can[i][j] = True
                            break

    # dp[i] = max blocks removable considering blocks[0..i-1]
    dp = [0] * (m+1)
    for i in range(1, m+1):
        dp[i] = dp[i-1]
        for j in range(0, i, 2):
            length = i - j
            if length % 2 == 0 and can[j][i-1]:
                dp[i] = max(dp[i], dp[j] + length)

