import sys

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    it = iter(data)
    out = []

    while True:
        try:
            n = int(next(it))
        except StopIteration:
            break
        if n == 0:
            break

        w = [int(next(it)) for _ in range(n)]

        # dp[l][r]: maximum number of removable blocks in interval [l, r]
        dp = [[0] * n for _ in range(n)]

        # length = interval length
        for length in range(2, n + 1):
            for l in range(n - length + 1):
                r = l + length - 1

                # Split into two parts
                best = 0
                for k in range(l, r):
                    v = dp[l][k] + dp[k + 1][r]
                    if v > best:
                        best = v

                # Remove whole interval if possible:
                # middle part must be fully removable, and ends differ by at most 1
                if abs(w[l] - w[r]) <= 1:
                    if length == 2:
                        best = max(best, 2)
                    elif dp[l + 1][r - 1] == length - 2:
                        best = max(best, length)

                dp[l][r] = best

        out.append(str(dp[0][n - 1]))

    sys.stdout.write("\n".join(out))

